-- Varikotsele sertifikat (Nazorat) test bankini amaliy (50) + USMLE (20) savollarini
-- birlashtirib to'ldirish — jami 70 savoldan har bir urinishda 20 tasi tasodifiy tanlanadi.
UPDATE public.dars_tarkibi
SET nazorat_savollar = $nazorat$[{"savol":"Varikoselening asosiy patofiziologik sababi qaysi jarayon hisoblanadi?","variantlar":["Arteriyalar tonusining oshishi","Venoz klapanlarning yetishmovchiligi","Limfa oqimining kuchayishi","Sperma kanalining torayishi"],"togri":1,"izoh":"Venoz klapanlar yetishmovchiligi qonning teskari oqishi (reflyuks)ga olib keladi — varikoselening asosiy mexanizmi."},{"savol":"Dubin-Amelar tasnifida faqat asbob yordamida (palpatsiyasiz) aniqlanadigan daraja qanday nomlanadi?","variantlar":["Yengil daraja","Og'ir daraja","Subklinik daraja","O'rta daraja"],"togri":2,"izoh":"Subklinik varikosele palpatsiya qilinmaydi, faqat Doppler UTT orqali aniqlanadi."},{"savol":"Varikosele tana tomonlaridan qaysi birida ko'pincha uchraydi?","variantlar":["O'ng tomonda","Chap tomonda","Ikkala tomonda teng","Faqat o'rta chiziqda"],"togri":1,"izoh":"Anatomik xususiyatlar (chap urug' venasining burchagi) sababli varikosele asosan chap tomonda uchraydi."},{"savol":"Pampiniform venoz pleksusning asosiy fiziologik vazifasi nima?","variantlar":["Spermani saqlash","Moshonka haroratini pasaytirish","Testosteron sintezlash","Siydikni filtrlash"],"togri":1,"izoh":"Bu pleksus issiqlik almashinuvi orqali moshonka haroratini tana haroratidan past saqlab, spermatogenezni qo'llab-quvvatlaydi."},{"savol":"Klinik tekshiruvda varikoselening kattalashishini kuchaytiruvchi sinama qaysi?","variantlar":["Murphy sinamasi","Valsalva sinamasi","Babinski sinamasi","Romberg sinamasi"],"togri":1,"izoh":"Valsalva sinamasi (zo'riqib nafas tutish) qorin ichi bosimini oshirib venoz reflyuksni kuchaytiradi."},{"savol":"Og'ir (III) darajali varikoselening tashqi ko'rinishi qanday tasvirlanadi?","variantlar":["Ko'zga ko'rinmaydigan kichik shish","Faqat Valsalvada bilinadigan tuguncha","Terining ostidan ko'rinadigan venalar to'plami","Faqat USI'da aniqlanadigan o'zgarish"],"togri":2,"izoh":"III daraja moshonka terisi orqali ko'zga ko'rinadigan, 'qurt to'plami' kabi venoz tugunlar bilan tavsiflanadi."},{"savol":"Varikoseleni tekshirishda bemorni issiq xonada ushlash nima uchun zarur?","variantlar":["Qon bosimini barqarorlashtirish uchun","Kremaster mushagini bo'shashtirib yashirin varikoseleni aniqlash uchun","Bemorni tinchlantirish uchun","Tekshiruv vaqtini qisqartirish uchun"],"togri":1,"izoh":"Sovuqda kremaster mushagi qisqarib moyakni tortadi, bu kichik varikoseleni yashirib qo'yishi mumkin."},{"savol":"Gidroselening varikoseledan asosiy farqi nimada?","variantlar":["Faqat o'ng tomonda uchraydi","Transilluminatsiya natijasi musbat bo'ladi","Faqat bolalarda uchraydi","Og'riq bilan kechadi"],"togri":1,"izoh":"Gidrosele suyuqlik to'plami bo'lgani uchun yorug'lik nurini o'tkazadi (transilluminatsiya musbat), varikoselede bunday belgi yo'q."},{"savol":"Spermatoselening tipik joylashuvi qayerda?","variantlar":["Urug' tizimchasi bo'ylab","Epididim ustida, alohida kista shaklida","Qovuq devorida","Prostata ichida"],"togri":1,"izoh":"Spermatosele epididim ustida joylashgan, sperma suyuqligi bilan to'lgan alohida kista hisoblanadi."},{"savol":"Varikoselening umumiy erkaklar populyatsiyasidagi taxminiy tarqalishi qanday?","variantlar":["Taxminan 2%","Taxminan 15%","Taxminan 45%","Taxminan 70%"],"togri":1,"izoh":"Umumiy populyatsiyada varikosele taxminan 15% (har 5-6 erkakdan birida) uchraydi."},{"savol":"OAT-sindromi qaysi uch ko'rsatkichning birgalikda pasayishini bildiradi?","variantlar":["Hajm, rang, pH","Konsentratsiya, harakatchanlik, morfologiya","Yosh, vazn, libido","Testosteron, LH, FSH"],"togri":1,"izoh":"OAT — Oligo (konsentratsiya), Astheno (harakatchanlik), Terato (morfologiya) ko'rsatkichlarining birgalikda pasayishi."},{"savol":"Varikoselektomiya atamasi nimani anglatadi?","variantlar":["Moyakni olib tashlash","Kengaygan venalarni bog'lash yoki kesib olish","Prostatani kichraytirish","Siydik yo'lini kengaytirish"],"togri":1,"izoh":"Varikoselektomiya — patologik kengaygan venalarni bartaraf etish maqsadidagi jarrohlik amaliyoti."},{"savol":"Quyidagi usullardan qaysi biri varikosele tashxisida eng ko'p ishlatiladigan instrumental vosita hisoblanadi?","variantlar":["Magnit-rezonans tomografiya","Kompyuter tomografiya","Mosjonka Doppler ultratovushi","Pozitron-emission tomografiya"],"togri":2,"izoh":"Doppler UTT klinik tekshiruvga qo'shimcha, eng ko'p ishlatiladigan instrumental usul hisoblanadi."},{"savol":"Varikoseleda urug' bezi haroratining ko'tarilishi qaysi jarayonga bevosita zarar yetkazadi?","variantlar":["Testosteron retseptorlariga","Spermatogenezga","Prostata sekretsiyasiga","Siydik chiqarish reflexiga"],"togri":1,"izoh":"Yuqori harorat spermatogenez jarayonini (spermatozoid yetilishini) bevosita buzadi."},{"savol":"Subklinik varikosele uchun odatiy tavsiya qaysi?","variantlar":["Darhol jarrohlik","Doimiy antibiotik","Dinamik kuzatuv","Gormonal terapiya"],"togri":2,"izoh":"Subklinik varikosele uchun fertillikka sezilarli ta'sir isbotlanmagani sabab dinamik kuzatuv tavsiya etiladi."},{"savol":"Chap urug' venasining chap buyrak venasiga to'g'ri burchak ostida qo'shilishi qanday natijaga olib keladi?","variantlar":["Arterial bosimning pasayishi","Gidrostatik bosim ustunining uzayishi","Limfa oqimining tezlashishi","Uretra torayishi xavfi"],"togri":1,"izoh":"To'g'ri burchak ostida qo'shilish uzunroq gidrostatik ustun yaratadi, bu chap tomonda reflyuks xavfini oshiradi."},{"savol":"O'ng urug' venasining pastki kovak venaga qiya burchak ostida qo'shilishi qanday himoya effektini beradi?","variantlar":["Bakteriyalardan himoya","'Tabiiy klapan' effekti orqali himoya","Haroratdan himoya","Travmadan himoya"],"togri":1,"izoh":"Qiya burchak 'tabiiy klapan' vazifasini bajarib, o'ng tomonda reflyuks ehtimolini kamaytiradi."},{"savol":"Varikoselening patofiziologiyasida oksidativ stress qaysi molekulyar oqibatga olib keladi?","variantlar":["Testosteron sintezining kuchayishi","Spermatozoid DNKsining fragmentatsiyasi","Prostata bezining kattalashishi","Siydik pH'sining o'zgarishi"],"togri":1,"izoh":"Yuqori oksidativ stress spermatozoid DNKsini shikastlab, fragmentatsiya va apoptoz ehtimolini oshiradi."},{"savol":"Izolyatsiyalangan, keskin boshlangan o'ng tomonlama varikosele qanday qo'shimcha tekshiruvni talab qiladi?","variantlar":["Faqat takroriy palpatsiya","Retroperitoneal massani inkor etish","Spermogramma takrorlash","Testosteron darajasini o'lchash"],"togri":1,"izoh":"Bunday holatda buyrak o'smasi kabi retroperitoneal patologiyani inkor etish uchun UTT/KT zarur."},{"savol":"Varikoseleli o'smirda jarrohlikka ko'rsatma bo'lishi mumkin bo'lgan topilma qaysi?","variantlar":["Bir martalik yengil og'riq","Ikkala moyak orasidagi progressiv hajm farqi","Tasodifiy aniqlangan subklinik shakl","Oilada varikosele tarixi"],"togri":1,"izoh":"Progressiv asimmetriya (hajm farqining kattalashib borishi) o'smirlarda jarrohlikka asosiy ko'rsatmalardan biri."},{"savol":"Mikroxirurgik varikoselektomiyaning klassik (konvensional ingvinal) usuldan asosiy ustunligi nimada?","variantlar":["Operatsiya vaqtining qisqaligi","Tomirlarni saqlab, asoratlarni kamaytirish","Narxining pastligi","Og'riqsizlantirishsiz bajarilishi"],"togri":1,"izoh":"Mikroskop yordamida nozik tuzilmalarni saqlash gidrosele va qaytalanish ko'rsatkichlarini minimallashtiradi."},{"savol":"Radiologik embolizatsiya usulining o'ziga xos kamchiligi nimada?","variantlar":["Gidrosele xavfi yuqori","Qaytalanish xavfi nisbatan yuqori","Faqat umumiy anesteziya talab qiladi","Arteriya doim shikastlanadi"],"togri":1,"izoh":"Embolizatsiyada gidrosele xavfi 0% bo'lsa-da, qaytalanish xavfi nisbatan yuqori (15-25%)."},{"savol":"Operatsiyadan keyin postoperativ gidroselening eng ko'p uchraydigan sababi nima?","variantlar":["Vas deferensning shikastlanishi","Limfa tomirlarining bog'lanishi","Antibiotik qabul qilinmasligi","Erta jismoniy faollik"],"togri":1,"izoh":"Operatsiya paytida limfa tomirlarining bilmasdan bog'lanishi suyuqlik to'planishi (gidrosele)ga olib keladi."},{"savol":"Past serum testosteron darajasi bilan murojaat qilgan varikoseleli bemorda jarrohlikdan kutilgan gormonal natija nima?","variantlar":["Testosteron darajasi o'zgarmaydi","Leydig hujayralari funksiyasi yaxshilanishi mumkin","Testosteron darajasi pasayadi","Faqat estrogen darajasi o'zgaradi"],"togri":1,"izoh":"Varikoselektomiya Leydig hujayralari funksiyasini yaxshilab, ba'zi bemorlarda serum testosteronni sezilarli oshiradi."},{"savol":"Sekundar (ikkinchi darajali) infertillik bilan murojaat qiluvchilarda varikosele chastotasi birinchi darajali infertillikka nisbatan qanday?","variantlar":["Ancha past","Deyarli bir xil","Sezilarli yuqori","Umuman uchramaydi"],"togri":2,"izoh":"Sekundar infertillikda varikosele chastotasi birinchi darajaliga (35%) nisbatan ancha yuqori (75-81%)."},{"savol":"Quyidagi tekshiruv usullaridan qaysi biri asosan radiologik embolizatsiyadan oldin/davomida qo'llaniladi?","variantlar":["Spermogramma","Venografiya","Orkidometriya","Termografiya"],"togri":1,"izoh":"Venografiya asosan embolizatsiya jarayonida diagnostik/davolash vositasi sifatida ishlatiladi."},{"savol":"Bemorda klinik varikosele, patologik spermogramma va bola ko'rishga intilish birikmasi aniqlansa, eng mos boshqaruv qaysi?","variantlar":["Faqat kuzatuv","Jarrohlikni ko'rib chiqish","Faqat vitamin terapiya","Antibiotik kursi"],"togri":1,"izoh":"Bu uch omilning birikmasi varikoselektomiyaga asosiy ko'rsatma hisoblanadi."},{"savol":"Mosjonka og'rig'i konservativ chora-tadbirlarga javob bermasa, qanday yondashuv ko'rib chiqiladi?","variantlar":["Davolashni butunlay to'xtatish","Varikoselektomiyani ko'rib chiqish","Faqat psixoterapiya","Hech narsa qilinmaydi"],"togri":1,"izoh":"Konservativ davoga chidamli og'riq sindromi mustaqil jarrohlik ko'rsatmasi hisoblanadi."},{"savol":"Quyidagilardan qaysi biri varikoselektomiyaning mustaqil ko'rsatmasi SIFATIDA ko'rib chiqilMAYDI?","variantlar":["Progressiv urug' bezi atrofiyasi","Konservativ davoga chidamli og'riq","Simptomsiz subklinik shakl","Patologik spermogramma + bola ko'rish intilishi"],"togri":2,"izoh":"Subklinik, simptomsiz varikosele uchun jarrohlik tavsiya etilmaydi — qolgan variantlar haqiqiy ko'rsatmalar."},{"savol":"24 yoshli bemorda o'ng tomonlama izolyatsiyalangan varikosele topilsa, birinchi shubha nimaga qaratiladi?","variantlar":["Oddiy anatomik variatsiya","Retroperitoneal patologiya ehtimoli","Albatta jarrohlik kerakligi","Bu holat ayollarda uchrashi"],"togri":1,"izoh":"Izolyatsiyalangan o'ng tomonlama varikosele kamdan-kam va retroperitoneal sabablarni inkor etish talab qiladi."},{"savol":"Ikkala tomonlama varikoselening aniqlanish chastotasi diagnostik usulga qarab qanday o'zgaradi?","variantlar":["Hech qachon ikkala tomon birga aniqlanmaydi","Sezgir usullarda chastota ancha yuqori bo'ladi","Faqat bolalarda ikkala tomon uchraydi","Ikkala tomon faqat operatsiyada aniqlanadi"],"togri":1,"izoh":"Diagnostik usulning sezgirligiga qarab ikkitomonlama varikosele aniqlanish chastotasi 80% gachaga yetishi mumkin."},{"savol":"Varikoseleli bemorda OAT-sindromidan tashqari androgen holatini baholash uchun qaysi tekshiruv o'tkaziladi?","variantlar":["Siydik tahlili","Serum testosteron darajasi","Prostata UTT","Qon guruhi"],"togri":1,"izoh":"Serum testosteron darajasi (odatda 280-300 ng/dL dan past bo'lsa gipoandrogenizm) androgen holatini baholaydi."},{"savol":"Doppler UTT'da varikoseleni tasdiqlovchi vena diametri bo'yicha qanday holat to'g'ri?","variantlar":["Aniq xalqaro standart mavjud","Yagona universal chegara yo'q","Diametr 10 mm dan oshsa albatta jarrohlik","Diametr faqat bolalarda o'lchanadi"],"togri":1,"izoh":"Adabiyotda yagona chegara yo'q, shu sabab klinik (palpatsiya) tekshiruv asosiy hisoblanadi."},{"savol":"Laparoskopik varikoselektomiyaning o'ziga xos, boshqa usullarda kam uchraydigan asorat xavfi nima?","variantlar":["Gidrosele","Ichak yoki tomir shikastlanishi","Qaytalanish","Og'riq"],"togri":1,"izoh":"Laparoskopik usulda qorin bo'shlig'iga kirish tufayli ichak/tomir shikastlanishi va havo emboliyasi xavfi mavjud."},{"savol":"Mikroxirurgik usulda urug' bezi arteriyasi shikastlanishi xavfi nima uchun past?","variantlar":["Arteriya umuman ko'rinmaydi","Mikroskop ingichka arteriyani aniq farqlashga yordam beradi","Arteriya operatsiyada qatnashmaydi","Arteriya doim avtomatik saqlanadi"],"togri":1,"izoh":"Operatsion mikroskop 1.0-1.5 mm li ingichka arteriyani aniq ko'rib, undan ehtiyotlanish imkonini beradi."},{"savol":"45 yoshli bemorda chap mosjonkada yangi aniqlangan varikosele va og'ir gematuriya birga kuzatilsa, qaysi tekshiruv ustuvor?","variantlar":["Faqat spermogramma","Buyrak/retroperitoneal tasvirlash","Faqat orkidometriya","Faqat simptomlar anketasi"],"togri":1,"izoh":"Gematuriya bilan birga keluvchi varikosele buyrak patologiyasini chetlab o'tish uchun tasvirlashni talab qiladi."},{"savol":"Bemorda subklinik varikosele, normal spermogramma va hozircha bola tug'dirish rejasi yo'q. Eng mos taktikani tanlang.","variantlar":["Darhol mikroxirurgik operatsiya","Dinamik kuzatuv","Skleroterapiya","Ikkala tomonlama orxiektomiya"],"togri":1,"izoh":"Ko'rsatma yo'q bo'lganda (subklinik, normal natijalar) jarrohlik tavsiya etilmaydi, kuzatuv yetarli."},{"savol":"Operatsiyadan 3 hafta o'tib, bemorda moshonkada og'riqsiz, yumshoq, transilluminatsiyasi musbat shish paydo bo'ldi. Eng ehtimoliy asorat?","variantlar":["Qaytalangan varikosele","Postoperativ gidrosele","Orxoepididimit","Urug' bezi atrofiyasi"],"togri":1,"izoh":"Transilluminatsiya musbat, yumshoq shish — limfa to'planishi natijasidagi gidroselega xos belgi."},{"savol":"16 yoshli o'smirda chap mosjonkada II-daraja varikosele, lekin moyak hajmi ikki tomonda bir xil. Eng mos qadam?","variantlar":["Darhol jarrohlik","Muntazam orkidometriya/UTT bilan kuzatuv","Antibiotikoterapiya","Hech qanday tekshiruv kerak emas"],"togri":1,"izoh":"Hajm normal bo'lsa, progressiyani nazorat qilish uchun muntazam kuzatuv (6-12 oyda) tavsiya etiladi."},{"savol":"Bemorda klinik varikosele va past testosteron bor, lekin u bola tug'dirishni xohlamaydi. Varikoselektomiyani ko'rib chiqishga qaysi omil asos bo'lishi mumkin?","variantlar":["Faqat estetik sabab","Androgen yetishmovchiligini yaxshilash potensiali","Bu holatda jarrohlik ko'rsatilmagan","Faqat yosh chegarasi"],"togri":1,"izoh":"Past testosteron bilan birga keladigan klinik varikoselede gormonal yaxshilanish kutilgan holda jarrohlik ko'rib chiqilishi mumkin."},{"savol":"Bemor minimal qaytalanishni ustuvor deb hisoblaydi. Qaysi jarrohlik usulini tavsiya qilasiz?","variantlar":["Konvensional ingvinal usul","Mikroxirurgik usul","Radiologik embolizatsiya","Farqi yo'q, tasodifiy tanlanadi"],"togri":1,"izoh":"Minimal qaytalanish ustuvor bo'lsa, mikroxirurgik usul eng past qaytalanish ko'rsatkichi (0.5-1%) tufayli tanlanadi."},{"savol":"Operatsiyadan keyin 4 oy o'tib spermogramma hali ham yomon. Bu holatda qanday fikr to'g'ri?","variantlar":["Operatsiya albatta muvaffaqiyatsiz bo'lgan","Tiklanish ko'proq vaqt talab qilishi mumkin","Darhol qayta operatsiya zarur","Bu natijaga e'tibor berilmaydi"],"togri":1,"izoh":"Spermatogenez tiklanishi individual farq qiladi, ba'zan standart 3-6 oydan ko'proq vaqt kerak bo'lishi mumkin, takror tekshirish maqsadga muvofiq."},{"savol":"Bemorda og'ir oligo-azoospermiya va ikkala tomonlama klinik varikosele bor. Standart tekshiruvlardan tashqari qaysi qo'shimcha tekshiruv ko'rib chiqiladi?","variantlar":["Faqat qayta spermogramma","Genomik (genetik) tekshiruv","Faqat UTT takrorlash","Faqat antibiotik kursi"],"togri":1,"izoh":"Og'ir oligo-/azoospermiyada genomik tekshiruv qo'shimcha sabablarni (genetik) inkor etish uchun ko'rib chiqiladi."},{"savol":"Jarroh operatsiya paytida urug' bezi arteriyasini bilmasdan bog'laydi. Bu xato qanday uzoq muddatli oqibatga olib kelishi mumkin?","variantlar":["Hech qanday oqibat bo'lmaydi","Urug' bezi atrofiyasi va spermatogenez buzilishi","Faqat vaqtinchalik shish","Testosteron darajasining oshishi"],"togri":1,"izoh":"Arteriya bog'lanishi qon ta'minotini buzib, urug' bezi atrofiyasi va spermatogenez yetishmovchiligiga olib kelishi mumkin."},{"savol":"Shifokor 'subklinik varikoseleni davolash fertillikni sezilarli yaxshilamaydi' deb tushuntiradi. Bu fikr qaysi klinik tamoyilga asoslangan?","variantlar":["Barcha topilma avtomatik davolanishi kerak","Aralashuv faqat isbotlangan foyda bo'lganda tavsiya etiladi","Subklinik varikosele mavjud emas","Faqat yosh bemorlar davolanadi"],"togri":1,"izoh":"Dalilga asoslangan tibbiyot tamoyili — faqat isbotlangan foyda bo'lganda aralashuv tavsiya etiladi."},{"savol":"58 yoshli bemorda yangi boshlangan o'ng tomonlama varikosele, vazn yo'qotish va anemiya bor. Qaysi tashxis birinchi navbatda inkor etilishi kerak?","variantlar":["Yosh bilan bog'liq oddiy o'zgarish","Buyrak hujayrali karsinoma","Oddiy infeksiya","Dehidratatsiya"],"togri":1,"izoh":"Yosh kattaroq bemorda sistemik belgilar bilan birga keluvchi yangi o'ng tomonlama varikosele onkologik sababni jiddiy shubha qildiradi."},{"savol":"Bemor operatsiyadan keyin erta (3-kuni) jinsiy aloqaga qaytishni so'raydi. Shifokorning tavsiyasi qanday bo'lishi kerak?","variantlar":["Ruxsat berish, cheklov yo'q","Kamida 1 haftagacha kutishni tavsiya qilish","Umuman jinsiy aloqaga kirmaslik, 6 oy","Faqat og'riq bo'lmasa ruxsat berish"],"togri":1,"izoh":"Standart tavsiya — jarrohlik joyining tiklanishi uchun kamida 1 hafta kutish."},{"savol":"Klinik tekshiruvda varikosele aniqlanmadi, lekin Doppler UTT'da yengil reflyuks ko'rinadi, bemor simptomsiz va fertil. Eng mos yondashuv?","variantlar":["Darhol mikroxirurgik operatsiya","Faol aralashuv shart emas, kuzatuv mumkin","Embolizatsiya zudlik bilan","Genomik tekshiruv zudlik bilan"],"togri":1,"izoh":"Faqat instrumental topilma, klinik ko'rsatma va simptom yo'q bo'lganda faol aralashuv asoslanmagan."},{"savol":"Tadqiqotda mikroxirurgik usul bilan operatsiya qilingan bemorlarning testosteron darajasi nazorat guruhiga nisbatan sezilarli oshgan. Bu natija qaysi mexanizm bilan izohlanadi?","variantlar":["Operatsiya testosteron in'eksiyasini o'z ichiga oladi","Leydig hujayralari funksiyasi yaxshilangan","Bemorlar gormonal dori ichgan","Natija tasodifiy, mexanizm yo'q"],"togri":1,"izoh":"Varikoselening venoz turg'unlik/issiqlik ta'siri bartaraf etilgach, Leydig hujayralari funksiyasi tabiiy ravishda yaxshilanishi mumkin."},{"savol":"Klinisist bemorga jarrohlikdan keyin natija kafolatlanmagan, ayniqsa ayol omillari aniqlanmagan holatlarda, deb tushuntiradi. Bu qaysi klinik haqiqatni aks ettiradi?","variantlar":["Erkak omili yagona sabab har doim","Natija ikki partnyorning kombinatsiyalangan holatiga bog'liq","Jarrohlik hech qachon yordam bermaydi","Ayol omilini tekshirish shart emas"],"togri":1,"izoh":"Homiladorlik natijasi juftlikning ikkala tomoni holatiga bog'liq — shu sabab er-xotin kompleks baholanishi tavsiya etiladi."},{"vinyetka":"19-yoshli yigit profilaktik ko'rikda chap mosjonkada og'riqsiz shish bilan murojaat qiladi. Tik turganda venoz tugunlar palpatsiya qilinadi, yotganda kamayadi, Valsalva kuchaytiradi.","savol":"Eng ehtimoliy tashxis qaysi?","variantlar":["Gidrosele","Varikosele","Spermatosele","Ingvinal gerniya"],"togri":1,"izoh":"Tik turganda ko'rinadigan, Valsalva bilan kuchayadigan, yotganda kamayadigan venoz tugunlar — varikoselening klassik klinik ko'rinishi."},{"vinyetka":"16-yoshli o'smirda chap mosjonkada faqat Valsalva sinamasi vaqtida palpatsiya qilinadigan tuguncha aniqlanadi, tinch holatda ko'rinmaydi.","savol":"Dubin-Amelar tasnifi bo'yicha bu qaysi daraja?","variantlar":["Subklinik daraja","Yengil (I) daraja","O'rtacha (II) daraja","Og'ir (III) daraja"],"togri":1,"izoh":"Faqat Valsalva sinamasi vaqtida palpatsiya qilinadigan, ko'rinmaydigan varikosele yengil (I) daraja hisoblanadi."},{"vinyetka":"22-yoshli erkak sovuq kabinetda tekshirilganda varikosele aniqlanmagan, ammo issiq xonada qaytadan tekshirilganda chap mosjonkada aniq tuguncha topilgan.","savol":"Bu farqning sababi nima?","variantlar":["Sovuqda qon bosimi oshadi","Kremaster mushagi qisqarib varikoseleni yashiradi","Issiq xonada vena torayadi","Farq tasodifiy, ahamiyati yo'q"],"togri":1,"izoh":"Sovuq sharoitda kremaster mushagining qisqarishi moyakni ko'tarib varikoseleni yashirishi mumkin."},{"vinyetka":"40-yoshli erkak surunkali bepushtlik bo'yicha tekshirilmoqda. Spermogrammada konsentratsiya, harakatchanlik va morfologiyaning barchasi pasaygan.","savol":"Bu spermogramma topilmasi qaysi sindrom bilan tavsiflanadi?","variantlar":["Azoospermiya sindromi","OAT-sindromi","Aspermiya sindromi","Hiperspermiya sindromi"],"togri":1,"izoh":"Konsentratsiya, harakatchanlik va morfologiyaning birgalikda pasayishi OAT-sindromi deb ataladi."},{"vinyetka":"26-yoshli erkak mosjonkada og'riq bilan murojaat qiladi: og'riq kechqurun uzoq tik turgandan keyin kuchayadi, yotganda yo'qoladi. NSPVD va support yordam bermayapti.","savol":"Bu bemor uchun keyingi mos qadam nima?","variantlar":["Faqat kuzatuv davom etadi","Varikoselektomiyani ko'rib chiqish","Darhol antibiotik berish","Testosteron in'eksiyasi"],"togri":1,"izoh":"Konservativ chora-tadbirlarga javob bermaydigan mosjonka og'rig'i varikoselektomiya uchun mustaqil ko'rsatmalardan biri."},{"vinyetka":"Shifokor varikoseleli bemorga UTT tayinlamoqda, lekin adabiyotlarda vena diametri bo'yicha yagona chegara yo'qligini tushuntiradi.","savol":"Bu holatda tashxis qo'yishda qaysi usul birinchi (ustun) hisoblanadi?","variantlar":["Ultratovush diametri","Klinik (palpatsiya) tekshiruv","Kompyuter tomografiya","Venografiya"],"togri":1,"izoh":"UTT'da universal chegara yo'qligi sababli, varikosele tashxisi birinchi navbatda klinik tekshiruvga asoslanadi."},{"vinyetka":"45-yoshli erkak bemor faqat Doppler UTT'da aniqlangan, palpatsiya qilinmaydigan varikosele bilan murojaat qiladi. Spermogramma normal, bola tug'dirish rejasi yo'q.","savol":"Eng to'g'ri boshqaruv taktikasi qaysi?","variantlar":["Darhol mikroxirurgik operatsiya","Dinamik kuzatuv, jarrohliksiz","Skleroterapiya o'tkazish","Bilateral orxiektomiya"],"togri":1,"izoh":"Subklinik varikosele, normal spermogramma va bola tug'dirish rejasi yo'q bo'lganda jarrohlik tavsiya etilmaydi."},{"vinyetka":"29-yoshli erkak varikoselektomiyadan 2 hafta o'tib, mosjonkada og'riqsiz suyuqlik to'planishi bilan murojaat qiladi. Transilluminatsiya pozitiv.","savol":"Bu asorat qaysi tomir tizimining shikastlanishi bilan bog'liq?","variantlar":["Arteriya tizimi","Limfa tomirlari","Vas deferens","Nerv tolalari"],"togri":1,"izoh":"Operatsiya paytida limfa tomirlarining bog'lanishi postoperativ gidroselening asosiy sababi hisoblanadi."},{"vinyetka":"19-yoshli o'smir yillik tekshiruvda chap mosjonkada II-daraja varikosele va o'ng moyakka solishtirganda chap moyak hajmining sezilarli kichikligi aniqlanadi.","savol":"Bu topilma qaysi qarorni qo'llab-quvvatlaydi?","variantlar":["Faqat kuzatuv, hech narsa qilinmaydi","Jarrohlikni ko'rib chiqish","Darhol orxiektomiya","Faqat gormonal terapiya"],"togri":1,"izoh":"O'smirlarda progressiv hajm asimmetriyasi varikoselektomiyaga ko'rsatma hisoblanadi."},{"vinyetka":"27-yoshli erkak infertillik bo'yicha tekshirilmoqda. Chap mosjonkada klinik varikosele va spermogrammada patologik o'zgarishlar aniqlandi. Xotini fertillik nuqtai nazaridan sog'lom.","savol":"Bu bemorda jarrohlik davolashga ko'rsatma bormi?","variantlar":["Yo'q, faqat dorivor davo kerak","Ha, ko'rsatma mavjud","Yo'q, faqat 40 yoshdan keyin","Ha, lekin faqat ikkala tomon zararlangan bo'lsa"],"togri":1,"izoh":"Klinik varikosele, patologik spermogramma va bola ko'rishga intilish birikmasi varikoselektomiyaga asosiy ko'rsatma."},{"vinyetka":"Tadqiqotchi varikoseleli va sog'lom erkaklarning urug' suyuqligini solishtirmoqda va varikoseleli guruhda yuqori darajadagi reaktiv oksigen turlari aniqlaydi.","savol":"Bu topilma spermatozoidlarga qanday ta'sir qiladi deb kutiladi?","variantlar":["Harakatchanlikni oshiradi","DNK fragmentatsiyasini kuchaytiradi","Hajmni kattalashtiradi","Hech qanday ta'siri yo'q"],"togri":1,"izoh":"Yuqori oksidativ stress spermatozoid DNKsining fragmentatsiyasini kuchaytiradi va apoptozni oshiradi."},{"vinyetka":"31-yoshli erkak past testosteron darajasi va klinik varikosele bilan murojaat qiladi. U charchoq va libido pasayishidan shikoyat qiladi.","savol":"Bu bemorda varikoselektomiya nimaga yordam berishi mumkin?","variantlar":["Hech qanday gormonal ta'sir bo'lmaydi","Serum testosteron darajasini oshirishi mumkin","Faqat spermatogenezga ta'sir qiladi","Testosteron darajasini pasaytiradi"],"togri":1,"izoh":"Mikroxirurgik varikoselektomiya Leydig hujayralari funksiyasini yaxshilab, serum testosteronni oshirishi mumkin."},{"vinyetka":"Jarroh varikoselektomiya paytida operatsion mikroskop yordamida urug' bezi arteriyasi, limfa tomirlari va vas deferensni ehtiyotkorlik bilan ajratib, faqat kengaygan venalarni bog'laydi.","savol":"Bu qaysi usulning tasviri va uning asosiy afzalligi nima?","variantlar":["Palomo usuli, tezligi bilan ustun","Mikroxirurgik usul, eng past asorat ko'rsatkichlari","Laparoskopik usul, narxi past","Venografiya, davolash usuli emas"],"togri":1,"izoh":"Mikroxirurgik usulning asosiy afzalligi — tomirlarni saqlab, gidrosele va qaytalanish ko'rsatkichlarini minimallashtirish."},{"vinyetka":"35-yoshli erkak varikoselektomiyadan keyin urug' bezi hajmining kichrayishi va spermatogenez yomonlashishi bilan murojaat qiladi.","savol":"Bu asoratning eng ehtimoliy sababi nima?","variantlar":["Urug' bezi arteriyasining bilmasdan bog'lanishi","Ortiqcha jismoniy faollik","Antibiotik qabul qilinmaganligi","Erta jinsiy aloqa"],"togri":0,"izoh":"Ingichka urug' bezi arteriyasining bilmasdan shikastlanishi atrofiya va spermatogenez buzilishiga olib kelishi mumkin."},{"vinyetka":"Radiolog varikosele bilan og'rigan bemorga noinvaziv, arteriya/limfa tomirlariga tegmaydigan, lekin qaytalanish xavfi nisbatan yuqori bo'lgan usulni taklif qiladi.","savol":"Bu qaysi davolash usuli?","variantlar":["Mikroxirurgik varikoselektomiya","Radiologik embolizatsiya","Palomo usuli","Laparoskopik usul"],"togri":1,"izoh":"Radiologik embolizatsiya arteriya/limfaga tegmagani uchun gidrosele xavfi 0%, lekin qaytalanish xavfi nisbatan yuqori (15-25%)."},{"vinyetka":"24-yoshli erkak mosjonkada o'ng tomonlama, palpatsiya qilinadigan tuguncha bilan murojaat qiladi. Chap tomonda hech narsa topilmaydi, boshqa tekshiruvlar normal.","savol":"Bu nostandart topilma haqida qaysi gap to'g'ri?","variantlar":["Bu juda oddiy holat, qo'shimcha tekshiruv kerak emas","Retroperitoneal patologiyani inkor etish zarur","Bu doim saraton degani","Faqat ayollarda uchraydigan holat"],"togri":1,"izoh":"Izolyatsiyalangan o'ng tomonlama varikosele kamdan-kam uchraydi va retroperitoneal massadan shubhalanishni talab qiladi."},{"vinyetka":"58-yoshli erkak bir necha hafta oldin to'satdan paydo bo'lgan o'ng tomonlama mosjonka shishi bilan murojaat qiladi. Anamnezda vazn yo'qotish va gematuriya bor.","savol":"Keyingi eng to'g'ri tekshiruv qadami nima?","variantlar":["Faqat kuzatuvni davom ettirish","Retroperitoneal tasvirlash o'tkazish","Antibiotikoterapiya boshlash","Darhol varikoselektomiya"],"togri":1,"izoh":"Keskin boshlangan o'ng tomonlama varikosele, sistemik belgilar bilan birga, retroperitoneal massani inkor etishni talab qiladi."},{"vinyetka":"33-yoshli erkak varikoselektomiyadan 4 oy o'tib, spermogramma ko'rsatkichlari hali ham yetarli yaxshilanmagan, lekin asta-sekin ijobiy tendensiya bor.","savol":"Bu holatda klinik fikrlash qanday bo'lishi kerak?","variantlar":["Operatsiya albatta muvaffaqiyatsiz hisoblanadi","Tiklanish davom etayotgan bo'lishi mumkin, kuzatuv davom etadi","Darhol qayta operatsiya zarur","Natijaga umuman e'tibor berilmaydi"],"togri":1,"izoh":"Spermatogenez tiklanishi bir necha oy davom etishi mumkin, ijobiy tendensiya bo'lsa, kuzatuvni davom ettirish maqsadga muvofiq."},{"vinyetka":"Bemor ikkala tomonlama klinik varikosele va og'ir azoospermiya bilan murojaat qiladi. Standart spermogramma va gormonal tekshiruvlar tugallangan.","savol":"Qaysi qo'shimcha tekshiruv ko'rib chiqilishi kerak?","variantlar":["Faqat takroriy spermogramma","Genomik (genetik) tekshiruv","Faqat qo'shimcha UTT","Faqat antibiotik sinovi"],"togri":1,"izoh":"Og'ir azoospermiyada genetik sabablarni inkor etish uchun genomik tekshiruv ko'rib chiqiladi."},{"vinyetka":"Klinisist er-xotin juftligiga varikoselektomiyadan keyin homiladorlik kafolatlanmasligini, chunki natija ikkala partnyor holatiga bog'liqligini tushuntiradi.","savol":"Bu tushuntirish qaysi klinik tamoyilni aks ettiradi?","variantlar":["Erkak omili yagona hal qiluvchi sabab","Fertillik natijasi ikki partnyorning kombinatsiyasiga bog'liq","Jarrohlik hech qachon natija bermaydi","Ayol omilini baholash shart emas"],"togri":1,"izoh":"Homiladorlik natijasi juftlikning ikkala tomoni holatiga bog'liq bo'lgani uchun kompleks baholash tavsiya etiladi."}]$nazorat$::jsonb,
